using System;using System.Linq;using IdleIntelligence.Core;using UnityEngine;using UnityEngine.UI;
namespace IdleIntelligence.Runtime {
 public sealed class LaboratoryView:MonoBehaviour {
  GameRuntime game;public Image ChargeFill,TrainingFill;public Text Production,Model,Training,Floating;public RectTransform Art;public Button Train,ModelButton;LabFeedback feedback;
  public void Initialize(GameRuntime runtime){game=runtime;feedback=game.TapButton.GetComponent<LabFeedback>()??game.TapButton.gameObject.AddComponent<LabFeedback>();feedback.Initialize(Floating);Train.onClick.AddListener(()=>game.UserShow("training"));ModelButton.onClick.AddListener(()=>game.UserShow(game.State.Prestige.lab?"models":"training"));}
  void OnEnable(){Canvas.preWillRenderCanvases+=Adapt;Adapt();}void OnDisable(){Canvas.preWillRenderCanvases-=Adapt;}void OnRectTransformDimensionsChange()=>Adapt();void Adapt(){var stage=transform.Find("LaboratoryStage");var canvas=GetComponentInParent<Canvas>();if(stage==null||canvas==null)return;var root=canvas.rootCanvas;var rect=root.renderMode==RenderMode.ScreenSpaceCamera&&root.worldCamera!=null?root.worldCamera.pixelRect:new Rect(0,0,Screen.width,Screen.height);float height=rect.height/Mathf.Max(1,rect.width)<1.9f?142:218;var size=stage.GetComponent<LayoutElement>();if(size!=null&&size.preferredHeight!=height)size.minHeight=size.preferredHeight=height;}
  void LateUpdate(){if(game?.State==null)return;Adapt();var s=game.State;bool de=s.Settings.language=="de";string N(ScientificNumber n)=>NumberFormatting.Format(n,s.Settings.numberFormat);bool active=s.ActiveUntil>s.SavedAt;ChargeFill.fillAmount=active?(float)Math.Max(0,(s.ActiveUntil-s.SavedAt)/1000/Balance.OverdriveMaxSeconds):(float)(s.Charge/Balance.OverdriveCharge);ChargeFill.color=active?GameTheme.Gold:GameTheme.Accent;Production.text="+"+N(Game.Income(s))+" /s  ·  +"+N(Game.DataRate(s))+" "+(de?"Daten":"Data")+" /s";game.TapButton.GetComponentInChildren<Text>().text=de?"Tippen · Credit-Impuls":"Tap · Credit pulse";Model.text=(string.IsNullOrEmpty(s.Retention.aiName)?"KI":s.Retention.aiName)+" · Lv. "+s.ModelLevel+"\n"+(string.IsNullOrEmpty(s.Workshop.activeModel)?(de?"Basismodell":"Base model"):MetaBalance.Models.First(m=>m.Id==s.Workshop.activeModel).Name+" "+s.Workshop.activeModelLevel);Training.text=s.Training!=null?(de?"Training läuft":"Training active")+" · "+Math.Max(0,(s.Training.required-s.Training.done)/Game.WorkSpeed(s)).ToString("F0")+" s":(de?"Qualität":"Quality")+" "+s.Quality+"  ·  "+(de?"Trainieren":"Train");if(TrainingFill!=null){TrainingFill.fillAmount=s.Training==null?0:(float)Math.Min(1,s.Training.done/s.Training.required);}bool reduced=s.Workshop.reducedMotion||!s.Settings.effects;Art.localScale=Vector3.one;feedback.State(active,reduced);var badge=transform.Find("LaboratoryStage/LabBadge").GetComponent<Text>();badge.text=active?"OVERDRIVE":"LAB / 01";badge.color=active?GameTheme.Gold:GameTheme.Accent;var guidance=transform.Find("Guidance");if(guidance!=null)guidance.gameObject.SetActive(s.Story.tutorial=="active"||s.Guidance.hasPinned||!game.Writable);}
 }
}
